def run_query(rows: list[dict], query: dict) -> list[dict]:
    select = query.get("select", [])
    where = query.get("where")
    group_by = query.get("group_by") or []
    having = query.get("having")
    distinct = query.get("distinct")
    order_by = query.get("order_by") or []
    offset = query.get("offset")
    limit = query.get("limit")

    def agg_name(func, arg):
        return "%s(%s)" % (func, arg)

    def t_not(a):
        if a is None:
            return None
        return not a

    def t_and(a, b):
        if a is False or b is False:
            return False
        if a is None or b is None:
            return None
        return True

    def t_or(a, b):
        if a is True or b is True:
            return True
        if a is None or b is None:
            return None
        return False

    def compare(op, a, b):
        if a is None or b is None:
            return None
        if op == "=":
            return a == b
        if op == "!=":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        if op == ">=":
            return a >= b
        raise ValueError("unknown operator: %r" % (op,))

    def evaluate(cond, resolve):
        op = cond[0]
        if op == "and":
            return t_and(evaluate(cond[1], resolve), evaluate(cond[2], resolve))
        if op == "or":
            return t_or(evaluate(cond[1], resolve), evaluate(cond[2], resolve))
        if op == "not":
            return t_not(evaluate(cond[1], resolve))
        if op == "is_null":
            return resolve(cond[1]) is None
        if op == "in":
            lst = cond[2]
            if not lst:
                return False
            x = resolve(cond[1])
            if x is None:
                return None
            has_null = False
            for e in lst:
                if e is None:
                    has_null = True
                elif e == x:
                    return True
            return None if has_null else False
        if op == "between":
            x = resolve(cond[1])
            return t_and(compare(">=", x, cond[2]), compare("<=", x, cond[3]))
        return compare(op, resolve(cond[1]), resolve(cond[2]))

    def compute_agg(func, arg, grows):
        if func == "count":
            if arg == "*":
                return len(grows)
            return sum(1 for r in grows if r[arg] is not None)
        vals = [r[arg] for r in grows if r[arg] is not None]
        if func == "count_distinct":
            return len(set(vals))
        if not vals:
            return None
        if func == "sum":
            return sum(vals)
        if func == "min":
            return min(vals)
        if func == "max":
            return max(vals)
        if func == "avg":
            return sum(vals) // len(vals)
        raise ValueError("unknown aggregate: %r" % (func,))

    # WHERE
    if where is not None:
        passed = []
        for r in rows:
            def res(operand, r=r):
                if operand[0] == "col":
                    return r[operand[1]]
                return operand[1]
            if evaluate(where, res) is True:
                passed.append(r)
    else:
        passed = list(rows)

    has_agg = any(not isinstance(item, str) for item in select)
    grouped = bool(group_by) or has_agg or having is not None

    output = []
    if grouped:
        groups = {}
        order = []
        if group_by:
            for r in passed:
                key = tuple(r[c] for c in group_by)
                g = groups.get(key)
                if g is None:
                    g = []
                    groups[key] = g
                    order.append(key)
                g.append(r)
        else:
            groups[()] = passed
            order.append(())

        for key in order:
            grows = groups[key]
            gvals = dict(zip(group_by, key))
            cache = {}

            def get_agg(func, arg, grows=grows, cache=cache):
                k = (func, arg)
                if k not in cache:
                    cache[k] = compute_agg(func, arg, grows)
                return cache[k]

            if having is not None:
                def res(operand, gvals=gvals, get_agg=get_agg):
                    kind = operand[0]
                    if kind == "col":
                        return gvals[operand[1]]
                    if kind == "agg":
                        return get_agg(operand[1], operand[2])
                    return operand[1]
                if evaluate(having, res) is not True:
                    continue

            out = {}
            for item in select:
                if isinstance(item, str):
                    out[item] = gvals[item]
                else:
                    out[agg_name(item[0], item[1])] = get_agg(item[0], item[1])
            output.append(out)
    else:
        for r in passed:
            output.append({c: r[c] for c in select})

    # DISTINCT
    if distinct:
        seen = set()
        uniq = []
        for o in output:
            k = tuple(o.values())
            if k not in seen:
                seen.add(k)
                uniq.append(o)
        output = uniq

    # ORDER BY (stable sorts from last key to first)
    for key, direction, nulls in reversed(order_by):
        desc = direction == "desc"
        nulls_first = nulls == "first" or (nulls is None and not desc)
        if desc:
            null_flag = 2 if nulls_first else 0
        else:
            null_flag = 0 if nulls_first else 2

        def sk(o, key=key, null_flag=null_flag):
            v = o[key]
            if v is None:
                return (null_flag, 0)
            return (1, v)

        output.sort(key=sk, reverse=desc)

    # OFFSET / LIMIT
    start = offset or 0
    if limit is None:
        output = output[start:]
    else:
        output = output[start:start + limit]
    return output
